///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getCode
 * @description etn발행사
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getCode = async function() {
    // etn발행사
    const sbmOptions = {
        id : "sbm_dts_EtnInst",
        action : "/etn/EtnCodeAct.do",
        ref : "",
        target : "dts_EtnInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_EtnSrty",
        action : "/etn/EtnCodeAct.do",
        ref : "",
        target : "dts_EtnSrty=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&inputMessageId=ETN_ISUR_SRTY_CREDIT_INOUT&outputMessageId=ETN_ISUR_SRTY_CREDIT_INOUT";
    url += "&ISUR_SRTY_CD=" + cbo_inst_srty.BindColVal;
    url += "&GUBUN=" + rdo_gubun.getValue();
    url += "&S_DATE=" + edt_SDate.getValue();
    url += "&E_DATE=" + edt_EDate.getValue();
    const sbmOptions = {
        id : "sbm_dts",
        action : "/etn/EtnStatMgt.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name popCreditDetail
 * @description pop Credit Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popCreditDetail = async function(row) {
    // frame.CreateDialogFrame("ULDSTF08061",".ULDSTF08061.gfm", "영업용순자본비율", 30, 50, 430, 575, "window");
    if (dts.getCellData(Number(row), "ACPT_NO") === "") return;
    // 2017-11-27 KBoY 비공개 첨부서류 볼 수 없음.
    await $c.stf.openDisclViewer(dts.setCellData(eval(row, function(edtSDate, edtEDate) {
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edtSDate.setValue($c.ut.cGetMinusYear(vCurDate, 3));
        edtEDate.setValue(vCurDate);
    }, async function() {
        if (rdo_gubun.getValue() === "2") {
            cbo_inst_srty.setDisabled(true);
            cbo_inst_srty.ComboDataID = "dts_EtnInst";
        } else if (rdo_gubun.getValue() === "3") {
            cbo_inst_srty.setDisabled(true);
            cbo_inst_srty.ComboDataID = "dts_EtnSrty";
        } else if (rdo_gubun.getValue() === "1") cbo_inst_srty.setDisabled(true);
        cbo_inst_srty.setSelectedIndex(0);
        await scwin.search();
    }, async function() {
        /*		if( cbo_inst_srty.index == 0 ) {
        			alert(getMessageParam("MSG-0016", ""));
        			cbo_inst_srty.focus();
        			return ;
        		}
         */
        await scwin.search();
    }, async function() {
        await $c.win.alert(dts);
    }, function(rowcount) {
        txb_TotCnt.setValue("총건수 : " + rowcount);
        //    FillGridHeaderTotalCnt(rowcount, panel_page);
        //    FillGridHeaderTotalCnt(rowcount);
    }, async function(row, colid) {
        await scwin.popCreditDetail(row);
    }, async function() {
        $c.pre_newlisting.fn_initSearchDate(edt_SDate, edt_EDate);
        const usrCBData = "1주일전^1,1개월전^2,3개월전^3,6개월전^4,1년전^5,2년전^6";
        cmb_PeriodTp.CBData = usrCBData; // 사용자CBData 지정

        rdo_gubun.setValue("1");
        await scwin.getCode();
        await scwin.search();
    }, async function() {
        await scwin.search();
    }, function() {
        window.close();
    }, function() {
        popUpCalendar2(edt_SDate);
    }, function() {
        popUpCalendar2(edt_EDate);
    }, function() {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    })));
};
